@page "/"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>RecipeShare - Home</PageTitle>

<div class="hero">
    <h1>Welcome to RecipeShare</h1>
    <p>Discover and share delicious recipes from around the world.</p>
</div>

<h2>Browse by Category</h2>

<div class="category-grid">
    @foreach (var category in RecipeService.GetCategories())
    {
        <a href="/categories/@category" class="category-card">
            <span class="category-icon">@GetCategoryIcon(category)</span>
            <span class="category-name">@category</span>
        </a>
    }
</div>

@code {
    private static string GetCategoryIcon(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Thai" => "🍜",
        "Mexican" => "🌮",
        "Japanese" => "🍱",
        _ => "🍽️"
    };
}

arguments.file_text:
@page "/categories"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>Categories - RecipeShare</PageTitle>

<h1>Recipe Categories</h1>

<div class="category-grid">
    @foreach (var category in RecipeService.GetCategories())
    {
        <a href="/categories/@category" class="category-card">
            <span class="category-icon">@GetCategoryIcon(category)</span>
            <span class="category-name">@category</span>
            <span class="category-count">@RecipeService.GetRecipesByCategory(category).Count recipes</span>
        </a>
    }
</div>

@code {
    private static string GetCategoryIcon(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Thai" => "🍜",
        "Mexican" => "🌮",
        "Japanese" => "🍱",
        _ => "🍽️"
    };
}

@page "/categories/{CategoryName}"
@using RecipeShare.Services
@using RecipeShare.Models
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeShare</PageTitle>

<h1>@CategoryName Recipes</h1>

<nav class="breadcrumb">
    <a href="/">Home</a> &rsaquo; <a href="/categories">Categories</a> &rsaquo; @CategoryName
</nav>

@if (Recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="recipe-list">
        @foreach (var recipe in Recipes)
        {
            <a href="/recipe/@recipe.Id" class="recipe-card">
                <h3>@recipe.Title</h3>
                <div class="recipe-rating">
                    @for (int i = 1; i <= 5; i++)
                    {
                        <span class="@(i <= Math.Round(recipe.AverageRating) ? "star filled" : "star")">★</span>
                    }
                    <span class="rating-text">@recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</span>
                </div>
            </a>
        }
    </div>
}

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Services
@using RecipeShare.Models
@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

@if (Recipe is null)
{
    <p>Recipe not found.</p>
}
else
{
    <nav class="breadcrumb">
        <a href="/">Home</a> &rsaquo; <a href="/categories">Categories</a> &rsaquo;
        <a href="/categories/@Recipe.Category">@Recipe.Category</a> &rsaquo; @Recipe.Title
    </nav>

    <article class="recipe-detail">
        <h1>@Recipe.Title</h1>

        <div class="recipe-meta">
            <span class="category-badge">@Recipe.Category</span>
            <span class="rating-display">
                @for (int i = 1; i <= 5; i++)
                {
                    <span class="@(i <= Math.Round(Recipe.AverageRating) ? "star filled" : "star")">★</span>
                }
                @Recipe.AverageRating.ToString("F1") (@Recipe.RatingCount ratings)
            </span>
        </div>

        <section class="recipe-section">
            <h2>Ingredients</h2>
            <ul>
                @foreach (var ingredient in Recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    <li>@ingredient</li>
                }
            </ul>
        </section>

        <section class="recipe-section">
            <h2>Steps</h2>
            @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <p>@step</p>
            }
        </section>

        <section class="recipe-section">
            <h2>Rate This Recipe</h2>
            <StarRating RecipeId="Recipe.Id" />
        </section>
    </article>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="star-rating-widget">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="@GetStarClass(star)" @onclick="() => Rate(star)" title="Rate @star stars">★</button>
    }
    @if (Submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int SelectedRating { get; set; }
    private bool Submitted { get; set; }

    private string GetStarClass(int star)
    {
        return star <= SelectedRating ? "star-btn filled" : "star-btn";
    }

    private void Rate(int stars)
    {
        SelectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        Submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (IsSubmitted)
{
    <div class="success-message">
        <h2>✅ Recipe Submitted!</h2>
        <p>Thank you for sharing "<strong>@Submission.Title</strong>" with the community.</p>
        <a href="/categories/@Submission.Category">View @Submission.Category recipes</a>
    </div>
}
else
{
    <EditForm Model="Submission" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />

        <div class="form-group">
            <label for="title">Recipe Title</label>
            <InputText id="title" @bind-Value="Submission.Title" placeholder="e.g. Grandma's Apple Pie" />
        </div>

        <div class="form-group">
            <label for="category">Category</label>
            <InputSelect id="category" @bind-Value="Submission.Category">
                <option value="">-- Select a category --</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Thai">Thai</option>
                <option value="Mexican">Mexican</option>
                <option value="Japanese">Japanese</option>
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="form-group">
            <label for="ingredients">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" @bind-Value="Submission.Ingredients" rows="6"
                placeholder="2 cups flour&#10;1 cup sugar&#10;3 apples, sliced" />
        </div>

        <div class="form-group">
            <label for="steps">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="Submission.Steps" rows="6"
                placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;3. ..." />
        </div>

        <button type="submit" class="btn-submit">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeSubmission Submission { get; set; } = new();
    private bool IsSubmitted { get; set; }

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(Submission.Title) ||
            string.IsNullOrWhiteSpace(Submission.Category) ||
            string.IsNullOrWhiteSpace(Submission.Ingredients) ||
            string.IsNullOrWhiteSpace(Submission.Steps))
        {
            return;
        }

        RecipeService.SubmitRecipe(Submission);
        IsSubmitted = true;
    }
}

