@page "/categories/{CategoryName}"
@using RecipeShare.Services
@using RecipeShare.Models
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeShare</PageTitle>

<h1>@CategoryName Recipes</h1>

<nav class="breadcrumb">
    <a href="/">Home</a> &rsaquo; <a href="/categories">Categories</a> &rsaquo; @CategoryName
</nav>

@if (Recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="recipe-list">
        @foreach (var recipe in Recipes)
        {
            <a href="/recipe/@recipe.Id" class="recipe-card">
                <h3>@recipe.Title</h3>
                <div class="recipe-rating">
                    @for (int i = 1; i <= 5; i++)
                    {
                        <span class="@(i <= Math.Round(recipe.AverageRating) ? "star filled" : "star")">★</span>
                    }
                    <span class="rating-text">@recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</span>
                </div>
            </a>
        }
    </div>
}

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Services
@using RecipeShare.Models
@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

@if (Recipe is null)
{
    <p>Recipe not found.</p>
}
else
{
    <nav class="breadcrumb">
        <a href="/">Home</a> &rsaquo; <a href="/categories">Categories</a> &rsaquo;
        <a href="/categories/@Recipe.Category">@Recipe.Category</a> &rsaquo; @Recipe.Title
    </nav>

    <article class="recipe-detail">
        <h1>@Recipe.Title</h1>

        <div class="recipe-meta">
            <span class="category-badge">@Recipe.Category</span>
            <span class="rating-display">
                @for (int i = 1; i <= 5; i++)
                {
                    <span class="@(i <= Math.Round(Recipe.AverageRating) ? "star filled" : "star")">★</span>
                }
                @Recipe.AverageRating.ToString("F1") (@Recipe.RatingCount ratings)
            </span>
        </div>

        <section class="recipe-section">
            <h2>Ingredients</h2>
            <ul>
                @foreach (var ingredient in Recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    <li>@ingredient</li>
                }
            </ul>
        </section>

        <section class="recipe-section">
            <h2>Steps</h2>
            @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <p>@step</p>
            }
        </section>

        <section class="recipe-section">
            <h2>Rate This Recipe</h2>
            <StarRating RecipeId="Recipe.Id" />
        </section>
    </article>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(Id);
    }
}

